gbmL(){return"\u0623\u0643\u062b\u0631 \u0645\u0646 \u0634\u0647\u0631\u064a\u0646"},
gOA(){return"\u0623\u0643\u0627\u062f\u064a\u0645\u064a\u0629 \u0627\u0644\u0646\u0627\u062f\u064a"},
gOG(){return"\u0647\u0630\u0627 \u0627\u0644\u0645\u0648\u0633\u0645"},
