gbjy(){return"\u0641\u0631\u064a\u0642 \u0644\u0627 \u064a\u062a\u0631\u0643 \u0644\u0644\u062e\u0635\u0645 \u0641\u0631\u0635\u0629 \u0644\u0627\u0644\u062a\u0642\u0627\u0637 \u0623\u0646\u0641\u0627\u0633\u0647."},
gbjA(){return"\u0641\u0631\u064a\u0642 \u064a\u0644\u0639\u0628 \u0628\u0642\u0644\u0628\u0647."},
gbjq(){return"\u0627\u0633\u062a\u0645\u0639 \u0623\u0648\u0644\u064b\u0627"},
ga2u(){return"\u062a\u062e\u0637\u064e\u0651"},
ga2t(){return"\u0623\u0639\u062f \u0633\u0645\u0627\u0639 \u0627\u0644\u0643\u0644\u0645\u0629"},
gbiW(){return"\u0627\u0644\u0642\u0627\u0626\u062f"},
aix(a){return"\u0627\u0644\u0641\u0631\u064a\u0642 \u064a\u0635\u063a\u064a \u0625\u0644\u064a\u0643. \u0633\u064a\u0631\u062f\u0651 \u0627\u0644\u0642\u0627\u0626\u062f \u0639\u0646\u062f \u0627\u0646\u062a\u0647\u0627\u0626\u0643\u061b \u0648\u0625\u0646 \u0644\u0645 \u062a\u0631\u063a\u0628 \u0641\u064a \u0627\u0644\u0627\u0646\u062a\u0638\u0627\u0631\u060c \u0641\u0627\u062e\u062a\u0631 **"+a+"**."},
aiq(a){return"\u0623\u0635\u063a\u0649 \u0627\u0644\u0641\u0631\u064a\u0642 \u0625\u0644\u064a\u0643 \u0648\u0631\u062f\u0651 \u0627\u0644\u0642\u0627\u0626\u062f. \u0627\u0644\u0622\u0646 **"+a+"**."},
gaGh(){return"\u062a\u0634\u0643\u064a\u0644 \u062a\u0644\u0642\u0627\u0626\u064a"},
aGf(a){return"\u064a\u064f\u0642\u062a\u0631\u062d "+a+" \u062a\u063a\u064a\u064a\u0631\u0627\u062a"},
